      "tipo": "GC",
      "causa_raiz": "Alocação contínua de memória gerenciada (5.14 MB por frame) causada pela concatenação de strings em laço ('s += i.ToString()') e pela criação de novos arrays de objetos ('new object[10000]') dentro do método Update(). Isso força coletas frequentes do Garbage Collector com pausas de até 22.75 ms, estourando o orçamento de 16.7 ms por frame.",
      "codigo_refatorado": "using System;\\nusing System.Text;\\nusing System.Collections.Generic;\\nusing UnityEngine;\\nusing UnityEngine.Pool;\\n\\nnamespace PerformanceAdvisor.StressTest\\n{\\n    public class StressTestScene : MonoBehaviour\\n    {\\n        public bool stressGc = false;\\n        public bool stressCpu = false;\\n        public bool stressDraw = false;\\n\\n        public GameObject testPrefab;\\n\\n        [Range(1, 20)]\\n        public float spawnRadius = 10f;\\n\\n        [Range(1, 50)]\\n        public int cubesPerFrame = 1;\\n\\n        public bool useUniqueMaterials = false;\\n\\n        [Range(1, 512)]\\n        public int cpuScansPerFrame = 1;\\n\\n        public int emptyObjects = 0;\\n        public int gcConcatIterations = 1000;\\n        public int gcArrayAllocs = 0;\\n        public int overdrawLayers = 0;\\n        public Material overdrawMaterial;\\n\\n        [Range(0, 2000)]\\n        public int prepopulateCount = 0;\\n\\n        private StringBuilder _stringBuffer;\\n        private readonly List<GameObject> _trackedObjects = new List<GameObject>();\\n        private ObjectPool<GameObject> _objectPool;\\n        private MaterialPropertyBlock _propBlock;\\n        private static readonly int ColorPropertyId = Shader.PropertyToID(\"_Color\");\\n\\n        private void Awake()\\n        {\\n            _stringBuffer = new StringBuilder(gcConcatIterations * 8);\\n            _propBlock = new MaterialPropertyBlock();\\n\\n            if (testPrefab != null)\\n            {\\n                _objectPool = new ObjectPool<GameObject>(\\n                    createFunc: () => Instantiate(testPrefab),\\n                    actionOnGet: go => go.SetActive(true),\\n                    actionOnRelease: go => go.SetActive(false),\\n                    actionOnDestroy: Destroy,\\n                    collectionCheck: false,\\n                    defaultCapacity: 128,\\n                    maxSize: 2048\\n                );\\n            }\\n        }\\n\\n        private void Start()\\n        {\\n            if (prepopulateCount > 0 && testPrefab != null)\\n            {\\n                for (int i = 0; i < prepopulateCount; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n\\n            for (int i = 0; i < emptyObjects; i++)\\n            {\\n                _trackedObjects.Add(new GameObject(\"Empty_\" + i));\\n            }\\n\\n            if (overdrawLayers > 0 && overdrawMaterial != null)\\n            {\\n                BuildOverdrawLayers();\\n            }\\n        }\\n\\n        private void BuildOverdrawLayers()\\n        {\\n            Camera cam = Camera.main;\\n            if (cam == null) return;\\n            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;\\n            for (int i = 0; i < overdrawLayers; i++)\\n            {\\n                float d = cam.nearClipPlane + 0.05f + i * 0.001f;\\n                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;\\n                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\\n                var col = quad.GetComponent<Collider>();\\n                if (col != null) Destroy(col);\\n                quad.name = \"Overdraw_\" + i;\\n                quad.transform.SetParent(cam.transform, false);\\n                quad.transform.localPosition = new Vector3(0f, 0f, d);\\n                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);\\n                var rend = quad.GetComponent<Renderer>();\\n                if (rend != null) rend.sharedMaterial = overdrawMaterial;\\n            }\\n        }\\n\\n        private void Update()\\n        {\\n            if (stressGc)\\n            {\\n                _stringBuffer.Clear();\\n                for (int i = 0; i < gcConcatIterations; i++)\\n                {\\n                    _stringBuffer.Append(i);\\n                }\\n            }\\n\\n            if (stressCpu)\\n            {\\n                for (int k = 0; k < cpuScansPerFrame; k++)\\n                {\\n                    int count = _trackedObjects.Count;\\n                    for (int i = 0; i < count; i++)\\n                    {\\n                        var obj = _trackedObjects[i];\\n                    }\\n                }\\n            }\\n\\n            if (stressDraw && testPrefab != null)\\n            {\\n                int n = Mathf.Max(1, cubesPerFrame);\\n                for (int i = 0; i < n; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n        }\\n\\n        private void SpawnOne()\\n        {\\n            GameObject clone = _objectPool != null ? _objectPool.Get() : Instantiate(testPrefab);\\n            clone.transform.position = UnityEngine.Random.insideUnitSphere * spawnRadius;\\n            clone.transform.rotation = Quaternion.identity;\\n            _trackedObjects.Add(clone);\\n\\n            if (useUniqueMaterials)\\n            {\\n                var rend = clone.GetComponent<Renderer>();\\n                if (rend != null)\\n                {\\n                    rend.GetPropertyBlock(_propBlock);\\n                    _propBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));\\n                    rend.SetPropertyBlock(_propBlock);\\n                }\\n            }\\n        }\\n\\n        private void OnDestroy()\\n        {\\n            _objectPool?.Dispose();\\n            _trackedObjects.Clear();\\n        }\\n    }\\n}",
      "explicacao_didatica": "Em C#, strings são imutáveis: toda vez que somamos texto com o operador '+', uma nova cópia é alocada na memória RAM (Managed Heap) e a anterior é descartada como lixo. Repetir isso milhares de vezes por segundo enche a memória muito rápido. Quando o Garbage Collector (o coletor de lixo da Unity) precisa limpar esses dados, ele congela todo o processamento do jogo por dezenas de milissegundos, gerando quedas de quadros perceptíveis para o jogador. Substituímos isso pelo StringBuilder, que reutiliza o mesmo espaço de memória pré-alocado sem gerar lixo."
    },
